PFP_FILE = "clivie_mm_pfp.png"

# Embedded Clivie MM profile picture.
# The image is automatically created from this data, so you do NOT need
# to manually place the PFP file in the Pydroid folder.
PFP_BASE64 = """"""

def ensure_pfp_file():
    if os.path.isfile(PFP_FILE):
        return True
    try:
        with open(PFP_FILE, "wb") as f:
            f.write(__import__("base64").b64decode(PFP_BASE64))
        return True
    except Exception as e:
        print("PFP file creation failed:", e)
        return False


client = TelegramClient("hassu_mm_session", API_ID, API_HASH)
counter = START_NUMBER


def money(value):
    return str(int(value)) if float(value).is_integer() else f"{float(value):.2f}"


def make_upi_qr(amount):
    # Use the fixed QR image supplied for Clivie MM.
    return os.path.isfile(QR_FILE)


async def set_group_photo(chat):
    # Automatically create/use the embedded Clivie MM PFP.
    if not ensure_pfp_file():
        return

    try:
        uploaded = await client.upload_file(PFP_FILE)
        await client(EditPhotoRequest(
            channel=chat,
            photo=InputChatUploadedPhoto(file=uploaded)
        ))
    except Exception as e:
        print("PFP skipped:", e)


async def create_mm_group():
    global counter

    group_name = "CIivie | Middleman"

    result = await client(CreateChannelRequest(
        title=group_name,
        about=GROUP_BIO,
        megagroup=True
    ))

    chat = result.chats[0]

    await set_group_photo(chat)

    terms_msg = await client.send_message(chat, TERMS)

    try:
        await client.pin_message(chat, terms_msg.id, notify=True)
    except Exception as e:
        print("Pin skipped:", e)

    try:
        invite = await client(ExportChatInviteRequest(peer=chat))
        link = invite.link
    except Exception as e:
        print("Invite link error:", e)
        link = "Invite link could not be generated."

    # Automatically add the helper bot to the newly-created MM group
    # and promote it to administrator.
    try:
        helper = await client.get_entity(HELPER_BOT)

        try:
            await client(InviteToChannelRequest(
                channel=chat,
                users=[helper]
            ))
        except Exception as e:
            # Telegram may report that the user is already a member.
            print("Helper invite skipped:", e)

        await client(EditAdminRequest(
            channel=chat,
            user_id=helper,
            admin_rights=ChatAdminRights(
                change_info=True,
                post_messages=True,
                edit_messages=True,
                delete_messages=True,
                ban_users=True,
                invite_users=True,
                pin_messages=True,
                add_admins=False,
                anonymous=False,
                manage_call=True
            ),
            rank="Admin"
        ))
        print(f"Helper bot added/promoted: {HELPER_BOT}")
    except Exception as e:
        print("Helper bot setup failed:", type(e).__name__, e)

    return group_name, link


# ============================================================
# /mm and /makemmgc
# ============================================================
@client.on(events.NewMessage(pattern=r"^/(mm|makemmgc)$"))
async def make_mm(event):
    if not event.is_private:
        return

    status_msg = None
    try:
        # Show the creating message while the group/PFP/link are being prepared.
        status_msg = await event.respond("⏳ Creating Clivie MM group + adding helper bot...")
        name, link = await create_mm_group()

        # Send the invite link first, then remove the temporary creating message.
        await event.respond(
            f"📎 Share the link below with anyone involved in this deal\n\n"
            f"{link}",
            link_preview=True
        )

        try:
            await status_msg.delete()
        except Exception as e:
            print("Creating message delete skipped:", e)

    except Exception as e:
        await event.respond(
            "❌ Group create nahi hua.\n\n"
            f"Error: {type(e).__name__}: {e}"
        )


# ============================================================
# /pay AMOUNT
# Example: /pay 200
# ============================================================
@client.on(events.NewMessage(pattern=r"^/pay\s+(\d+(?:\.\d+)?)$"))
async def pay_command(event):
    if not event.is_group:
        return

    try:
        deal_amount = float(event.pattern_match.group(1))
        total = deal_amount + FEE

        qr_ok = make_upi_qr(total)

        # Wrap the UPI ID in Telegram's monospace/code formatting so it is
        # easy to tap/copy on Telegram clients.
        upi_copy = f"<code>{PAY_UPI}</code>"

        text = (
            f"Pay Deal Amount + Fee: ₹{money(deal_amount)} + ₹{money(FEE)}\n"
            f"Total Amount: ₹{money(total)} INR\n\n"
            f"To UPI: {upi_copy}"
        )

        if qr_ok:
            await client.send_file(
                event.chat_id,
                QR_FILE,
                caption=text,
                parse_mode="html",
                reply_to=event.id
            )
        else:
            # Replace the old QR error with the Clivie QR username.
            await event.reply(
                text + "\n\n@CIivieqr",
                parse_mode="html",
                reply_to=event.id
            )

    except Exception:
        await event.reply("❌ Invalid amount. Example: `/pay 200`")



# ============================================================
# /RCVD
# ============================================================
@client.on(events.NewMessage(pattern=r"^/rcv\s+(\d+(?:\.\d+)?)$"))
async def rcvd_command(event):
    if not event.is_group:
        return

    try:
        amount = float(event.pattern_match.group(1))
        await event.reply(
            "Payment Received\n\n"
            f"I am holding ₹{money(amount)} amount\n"
            "You can continue your deal"
        )

        # Change the group name to the amount currently received.
        try:
            new_title = f"{money(amount)}₹ MM'D | CIivie | Middleman"
            await client(EditTitleRequest(
                channel=event.chat_id,
                title=new_title
            ))
        except Exception as e:
            print("Group title update skipped:", e)
    except Exception:
        await event.reply("❌ Invalid amount. Example: `/rcv 200`")



# ============================================================
# /sent UPI_ID
# Example: /sent jaiswalhuh@fam
# ============================================================
@client.on(events.NewMessage(pattern=r"^/sent\s+(.+)$"))
async def sent_command(event):
    if not event.is_group:
        return

    upi_id = event.pattern_match.group(1).strip()

    await event.reply(
        "Funds Released\n\n"
        "Funds have been sent to your UPI ID #buys\n\n"
        f"UPI ID: {upi_id}\n\n"
        "MM Service Complete"
    )


# ============================================================
# /complete
# ============================================================
@client.on(events.NewMessage(pattern=r"^/complete$"))
async def complete_command(event):
    if not event.is_group:
        return

    await event.reply(
        "Thank you for using my Middleman service!\n\n"
        "Please leave me a vouch below:\n\n"
        "Tap the text below to copy:\n\n"
        "<code>Vouch @CIivie for MM'd</code>",
        parse_mode="html"
    )


# ============================================================
# START
# ============================================================
async def main():
    ensure_pfp_file()

    print("================================")
    print("Clivie MM is starting...")
    print("================================")

    await client.start(phone=PHONE)

    me = await client.get_me()
    print(f"Logged in as: {me.first_name} (@{me.username or 'no_username'})")
    print("Clivie MM is RUNNING.")
    print("Commands: /mm, /makemmgc, /pay AMOUNT, /rcv AMOUNT, /sent UPI_ID, /complete")

    await client.run_until_disconnected()


if __name__ == "__main__":
    asyncio.run(main())
